    for j in range(n + 1):
        L[0][j] = 0

    # llenar la matriz utilizando programación dinámica
    for I in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])

    # obtener la subsecuencia más larga común a partir de la última entrada de la matriz
    index_i, index_j = m, n
    lcs = []
    while index_i > 0 and index_j > 0:
        if str1[index_i - 1] == str2[index_j - 1]:
            lcs.append(str1[index_i - 1])
            index_i -= 1
            index_j -= 1
        elif L[index_i - 1][index_j] > L[index_i][index_j - 1]:
            index_i -= 1
        else:
            index_j -= 1

    # revertir la subsecuencia para obtener la secuencia correcta
    lcs.reverse()

    return ''.join(lcs), L[m][n]
