class Queue:
    def __init__(self):
        self.front_stack = []
        self.back_stack = []

    def enqueue(self, item):
        self.back_stack.append(item)
        self._move_back_to_front()

    def dequeue(self):
        if not self.front_stack:
            self._move_front_to_back()
        return self.front_stack.pop()

    def _move_back_to_front(self):
        if not self.front_stack:
